import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Nhân vật và Tổ chức Quan trọng","description":"","frontmatter":{},"headers":[],"relativePath":"vi/95-关键人物与组织.md","filePath":"vi/95-关键人物与组织.md"}'),g={name:"vi/95-关键人物与组织.md"};function a(d,n,u,o,r,l){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="nhan-vat-va-to-chuc-quan-trong" tabindex="-1">Nhân vật và Tổ chức Quan trọng <a class="header-anchor" href="#nhan-vat-va-to-chuc-quan-trong" aria-label="Permalink to &quot;Nhân vật và Tổ chức Quan trọng&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>95</td></tr><tr><td>Mô-đun</td><td>Phụ lục và Tài liệu Tham khảo</td></tr><tr><td>Từ khóa chính</td><td>nhân vật quan trọng, tổ chức quan trọng, vai trò lịch sử, chức năng thể chế, văn minh cộng sinh</td></tr></tbody></table><h2 id="_1-mo-ta" tabindex="-1">1. Mô tả <a class="header-anchor" href="#_1-mo-ta" aria-label="Permalink to &quot;1. Mô tả&quot;">​</a></h2><p>Tài liệu này bao gồm các nhân vật quan trọng và tổ chức quan trọng trong quá trình phát triển của Văn minh Cộng sinh Mỏ neo, được phân loại và sắp xếp theo thời kỳ lịch sử và loại tổ chức. Phần nhân vật quan trọng liệt kê tên nhân vật, thời kỳ, đóng góp cốt lõi và vị trí lịch sử; phần tổ chức quan trọng liệt kê tên tổ chức, thời gian thành lập, chức năng cốt lõi và vai trò lịch sử. Tài liệu này là tài liệu cập nhật động; với sự tiến bộ của lịch sử và sự tiến hóa của các tổ chức, sẽ tiếp tục được bổ sung và sửa đổi.</p><h2 id="_2-nhan-vat-quan-trong" tabindex="-1">2. Nhân vật Quan trọng <a class="header-anchor" href="#_2-nhan-vat-quan-trong" aria-label="Permalink to &quot;2. Nhân vật Quan trọng&quot;">​</a></h2><h3 id="_2-1-nhung-nguoi-tien-phong-tu-tuong-trong-thoi-ky-tien-mo-neo" tabindex="-1">2.1 Những người tiên phong tư tưởng trong thời kỳ tiền-mỏ neo <a class="header-anchor" href="#_2-1-nhung-nguoi-tien-phong-tu-tuong-trong-thoi-ky-tien-mo-neo" aria-label="Permalink to &quot;2.1 Những người tiên phong tư tưởng trong thời kỳ tiền-mỏ neo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên nhân vật</th><th>Thời kỳ</th><th>Đóng góp cốt lõi</th><th>Vị trí lịch sử</th></tr></thead><tbody><tr><td>Huyền Hằng tử</td><td>Khoảng -500 triệu năm</td><td>Nhà tư tưởng đầu tiên phản ánh có hệ thống về hệ thống tu luyện kiểu cướp bóc, đề xuất nguyên mẫu của khái niệm &quot;cộng sinh&quot;, tác giả của tập bản thảo &quot;Luận chống cướp bóc&quot;</td><td>Người tiên phong cổ xưa của tư tưởng cộng sinh, tư tưởng của ông, sau hàng trăm triệu năm ngủ quên, đã trở thành nguồn tinh thần của Văn minh Cộng sinh Mỏ neo</td></tr><tr><td>Vạn Linh mẫu</td><td>Khoảng -100 triệu năm</td><td>Lãnh đạo văn minh thử nghiệm cộng sinh quy mô lớn đầu tiên; mặc dù cuối cùng bị văn minh kiểu cướp bóc phá hủy, nhưng thực hành của ông đã chứng minh tính khả thi của hệ thống cộng sinh</td><td>Người đi trước trong thực hành cộng sinh, được các thế hệ sau tôn kính là &quot;Mẹ của Cộng sinh&quot;</td></tr><tr><td>Mảo Giác giả</td><td>Khoảng -10.000 năm</td><td>Một người tu luyện từ mặt phẳng đầu tiên, tình cờ cảm nhận được các nút ổn định trong mạng lưới quy luật trong quá trình tu luyện dài hạn, phát hiện ra cơ chế mỏ neo</td><td>Người phát hiện cơ chế mỏ neo, người khai mở thời kỳ thức tỉnh mỏ neo</td></tr></tbody></table><h3 id="_2-2-nhung-nguoi-đat-nen-mong-cua-thoi-ky-thuc-tinh-mo-neo" tabindex="-1">2.2 Những người đặt nền móng của thời kỳ thức tỉnh mỏ neo <a class="header-anchor" href="#_2-2-nhung-nguoi-đat-nen-mong-cua-thoi-ky-thuc-tinh-mo-neo" aria-label="Permalink to &quot;2.2 Những người đặt nền móng của thời kỳ thức tỉnh mỏ neo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên nhân vật</th><th>Thời kỳ</th><th>Đóng góp cốt lõi</th><th>Vị trí lịch sử</th></tr></thead><tbody><tr><td>Mảo Định công</td><td>-10000 đến -9200 năm</td><td>Đệ tử của Mảo Giác giả, nghiên cứu có hệ thống về cơ chế mỏ neo, xây dựng mỏ neo nhân tạo đầu tiên, tác giả của &quot;Nguyên lý Mỏ neo&quot;</td><td>Người đặt nền móng cho công nghệ mỏ neo, người phát minh ra mỏ neo nhân tạo</td></tr><tr><td>Cộng Sinh tử</td><td>-6000 đến -5100 năm</td><td>Kết hợp công nghệ mỏ neo với tư tưởng cộng sinh, sáng tạo hệ thống lý luận &quot;Cộng sinh Mỏ neo&quot;, tác giả của &quot;Luận Cộng sinh Mỏ neo&quot;</td><td>Người sáng tạo lý luận cộng sinh mỏ neo, người thầy tinh thần của văn minh cộng sinh</td></tr><tr><td>Hằng Nguyên công</td><td>-5000 đến -4300 năm</td><td>Xây dựng thành phố-quốc gia kiểu cộng sinh đầu tiên dựa trên mỏ neo, &quot;Thành phố Hằng Nguyên&quot;, và thành công đánh lui cuộc tấn công của văn minh kiểu cướp bóc</td><td>Người xây dựng thành phố-quốc gia kiểu cộng sinh đầu tiên, người thực hành hệ thống cộng sinh</td></tr><tr><td>Vạn Tộc sứ</td><td>-2000 đến -1200 năm</td><td>Khởi xướng &quot;Hội nghị Cộng sinh Tất cả các Chủng tộc&quot; đầu tiên, chạy qua hàng chục chủng tộc để ủng hộ liên minh cộng sinh</td><td>Người ủng hộ liên minh tất cả các chủng tộc, người tiên phong của cộng sinh liên chủng tộc</td></tr></tbody></table><h3 id="_2-3-nhung-nguoi-sang-lap-nha-nuoc-trong-giai-đoan-thanh-lap-he-thong-cong-sinh" tabindex="-1">2.3 Những người sáng lập nhà nước trong giai đoạn thành lập hệ thống cộng sinh <a class="header-anchor" href="#_2-3-nhung-nguoi-sang-lap-nha-nuoc-trong-giai-đoan-thanh-lap-he-thong-cong-sinh" aria-label="Permalink to &quot;2.3 Những người sáng lập nhà nước trong giai đoạn thành lập hệ thống cộng sinh&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên nhân vật</th><th>Thời kỳ</th><th>Đóng góp cốt lõi</th><th>Vị trí lịch sử</th></tr></thead><tbody><tr><td>Lập Hiến công</td><td>-1000 đến -900 năm</td><td>Chủ tịch Ủy ban Soạn thảo Hiến pháp Cộng sinh, chủ trì soạn thảo &quot;Hiến pháp Cộng sinh&quot;, thúc đẩy việc thông qua hiến pháp bằng trưng cầu dân ý toàn dân</td><td>Người soạn thảo chính của Hiến pháp Cộng sinh, cha của hiến pháp văn minh cộng sinh</td></tr><tr><td>Chấp Pháp công</td><td>-900 đến -780 năm</td><td>Chủ tịch đầu tiên của Ủy ban Hành chính Cộng sinh, chủ trì xây dựng hệ thống hành chính và cơ chế thi hành pháp luật của văn minh cộng sinh</td><td>Người xây dựng hệ thống hành chính cộng sinh, người đứng đầu hành chính đầu tiên</td></tr><tr><td>Tư Pháp mẫu</td><td>-900 đến -800 năm</td><td>Chánh án đầu tiên của Tòa án Cộng sinh, xây dựng hệ thống tư pháp và hệ thống xem xét vi hiến của văn minh cộng sinh</td><td>Người xây dựng hệ thống tư pháp cộng sinh, người đứng đầu tư pháp đầu tiên</td></tr><tr><td>Tam Bách sư</td><td>-500 đến -300 năm</td><td>Chủ trì công việc khai quật và sắp xếp hệ thống tu luyện nguồn gốc ba trăm bộ, dẫn đầu đội ngũ hoàn thành việc xác minh tất cả ba trăm bộ hệ thống</td><td>Người sắp xếp tổng thể hệ thống ba trăm bộ, tổng chỉ huy dự án mở cửa tu luyện</td></tr><tr><td>Bội Tăng công</td><td>-300 đến -220 năm</td><td>Chủ trì nghiên cứu ứng dụng công nghệ của trái nhân đôi, đạt được đột phá kỹ thuật của công nghệ khuếch đại suy luận trăm lần</td><td>Nhà khoa học trưởng của công nghệ hóa trái nhân đôi, người thúc đẩy hệ thống lặp lại suy luận</td></tr></tbody></table><h3 id="_2-4-nhung-nguoi-lanh-đao-trong-giai-đoan-mo-cua-va-kich-hoat" tabindex="-1">2.4 Những người lãnh đạo trong giai đoạn mở cửa và kích hoạt <a class="header-anchor" href="#_2-4-nhung-nguoi-lanh-đao-trong-giai-đoan-mo-cua-va-kich-hoat" aria-label="Permalink to &quot;2.4 Những người lãnh đạo trong giai đoạn mở cửa và kích hoạt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên nhân vật</th><th>Thời kỳ</th><th>Đóng góp cốt lõi</th><th>Vị trí lịch sử</th></tr></thead><tbody><tr><td>Khai Phóng công</td><td>-100 đến -50 năm</td><td>Chủ trì công việc mở cửa hoàn toàn hệ thống tu luyện nguồn gốc ba trăm bộ, xây dựng hệ thống phân bổ tài nguyên tu luyện và mạng lưới cố vấn</td><td>Tổng chỉ huy của việc mở cửa hệ thống ba trăm bộ, người thực hành &quot;mọi người đều có con đường&quot;</td></tr><tr><td>Kích Hoạt công</td><td>-50 năm đến năm gốc</td><td>Chủ trì thực hiện chiến lược kích hoạt 20%, dẫn đầu đội ngũ hoàn thành mục tiêu kích hoạt 20% chúng sinh trong 50 năm</td><td>Tổng chỉ huy của chiến lược kích hoạt 20%, người khai mở kỷ nguyên mới của văn minh cộng sinh</td></tr><tr><td>Thăng Duy công</td><td>Năm gốc đến 80 năm</td><td>Chủ trì dự án nâng chiều không gian đầu tiên, thúc đẩy thực hiện con đường nâng chiều không gian bốn giai đoạn, đạt được nâng chiều không gian theo giai đoạn đầu tiên</td><td>Tổng kỹ sư của nâng chiều không gian đầu tiên, người lãnh đạo kỷ nguyên nâng chiều không gian</td></tr></tbody></table><h3 id="_2-5-nhung-nguoi-kham-pha-trong-thoi-ky-cong-hoa-tat-ca-cac-chung-toc-va-lien-mat-phang" tabindex="-1">2.5 Những người khám phá trong thời kỳ cộng hòa tất cả các chủng tộc và liên mặt phẳng <a class="header-anchor" href="#_2-5-nhung-nguoi-kham-pha-trong-thoi-ky-cong-hoa-tat-ca-cac-chung-toc-va-lien-mat-phang" aria-label="Permalink to &quot;2.5 Những người khám phá trong thời kỳ cộng hòa tất cả các chủng tộc và liên mặt phẳng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên nhân vật</th><th>Thời kỳ</th><th>Đóng góp cốt lõi</th><th>Vị trí lịch sử</th></tr></thead><tbody><tr><td>Vạn Tộc Cộng Chủ</td><td>100 đến 200 năm</td><td>Chủ trì công việc thành lập Cộng hòa Tất cả các Chủng tộc, thúc đẩy biên soạn danh mục tất cả các chủng tộc và chính sách hòa nhập liên chủng tộc</td><td>Người sáng lập Cộng hòa Tất cả các Chủng tộc, người đứng đầu Cộng hòa Tất cả các Chủng tộc đầu tiên</td></tr><tr><td>Vị Diện mẫu</td><td>500 đến 650 năm</td><td>Giám đốc đầu tiên của Cục Quản lý Mặt phẳng, chủ trì kế hoạch khám phá liên mặt phẳng quy mô lớn, xây dựng ngân hàng tọa độ mặt phẳng chung</td><td>Người khai mở khám phá liên mặt phẳng, người xây dựng hệ thống quản lý mặt phẳng</td></tr><tr><td>Khảo Cổ công</td><td>800 đến 950 năm</td><td>Chủ trì sự trưởng thành cuối cùng của kế hoạch khảo cổ từ xa bằng gương sao chép, thúc đẩy khảo cổ liên mặt phẳng bước vào kỷ nguyên quy mô</td><td>Người tập thành tựu của kế hoạch khảo cổ, người đặt nền móng cho khảo cổ liên mặt phẳng</td></tr><tr><td>Thời Luật công</td><td>1000 đến 1150 năm</td><td>Chủ trì đột phá công nghệ hồi quy thời gian, thúc đẩy việc thiết lập nguyên tắc &quot;quan sát trước, sau đó can thiệp hạn chế&quot;</td><td>Người lãnh đạo công nghệ hồi quy thời gian, người đặt ra các nguyên tắc luật thời gian</td></tr></tbody></table><h2 id="_3-to-chuc-quan-trong" tabindex="-1">3. Tổ chức Quan trọng <a class="header-anchor" href="#_3-to-chuc-quan-trong" aria-label="Permalink to &quot;3. Tổ chức Quan trọng&quot;">​</a></h2><h3 id="_3-1-co-quan-quyen-luc-toi-cao" tabindex="-1">3.1 Cơ quan quyền lực tối cao <a class="header-anchor" href="#_3-1-co-quan-quyen-luc-toi-cao" aria-label="Permalink to &quot;3.1 Cơ quan quyền lực tối cao&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên tổ chức</th><th>Thời gian thành lập</th><th>Chức năng cốt lõi</th><th>Vai trò lịch sử</th></tr></thead><tbody><tr><td>Hội đồng Mỏ neo</td><td>-900 năm</td><td>Cơ quan quyền lực tối cao của văn minh cộng sinh, bao gồm đại diện tất cả các chủng tộc theo tỷ lệ, thực hiện quyền lập pháp và quyền ra quyết định về các vấn đề quan trọng</td><td>Cơ quan ra quyết định tối cao của văn minh cộng sinh, người đặt ra tất cả các luật và chiến lược quan trọng</td></tr><tr><td>Ủy ban Hành chính Cộng sinh</td><td>-900 năm</td><td>Cơ quan hành chính tối cao của văn minh cộng sinh, chịu trách nhiệm thi hành hiến pháp và luật, quản lý hàng ngày</td><td>Cơ quan hành chính tối cao của văn minh cộng sinh, người thi hành luật và chính sách</td></tr><tr><td>Tòa án Cộng sinh</td><td>-900 năm</td><td>Cơ quan tư pháp tối cao của văn minh cộng sinh, thực hiện độc lập quyền xét xử, chịu trách nhiệm xem xét vi hiến và xét xử các vụ án quan trọng</td><td>Cơ quan tư pháp tối cao của văn minh cộng sinh, người bảo vệ pháp trị</td></tr><tr><td>Ủy ban Giám sát Mỏ neo</td><td>-900 năm</td><td>Cơ quan giám sát độc lập, chịu trách nhiệm giám sát tất cả các cơ quan quyền lực, ngăn chặn lạm dụng quyền lực</td><td>Cơ quan giám sát độc lập của văn minh cộng sinh, mắt xích quan trọng trong cân bằng quyền lực</td></tr></tbody></table><h3 id="_3-2-co-quan-quan-ly-chuyen-nganh" tabindex="-1">3.2 Cơ quan quản lý chuyên ngành <a class="header-anchor" href="#_3-2-co-quan-quan-ly-chuyen-nganh" aria-label="Permalink to &quot;3.2 Cơ quan quản lý chuyên ngành&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên tổ chức</th><th>Thời gian thành lập</th><th>Chức năng cốt lõi</th><th>Vai trò lịch sử</th></tr></thead><tbody><tr><td>Cục Quản lý Mặt phẳng</td><td>500 năm</td><td>Chịu trách nhiệm duy trì ngân hàng tọa độ mặt phẳng chung, phê duyệt giấy phép du hành, quản lý khảo cổ liên mặt phẳng, điều phối ngoại giao liên mặt phẳng</td><td>Cơ quan chủ quản của tương tác liên mặt phẳng, người quản lý khám phá mặt phẳng</td></tr><tr><td>Ủy ban Luật Thời gian</td><td>1000 năm</td><td>Chịu trách nhiệm phê duyệt hoạt động hồi quy thời gian, nghiên cứu luật thời gian, giám sát phòng ngừa nghịch lý thời gian</td><td>Cơ quan phê duyệt và giám sát hoạt động hồi quy thời gian, người bảo vệ an toàn luật thời gian</td></tr><tr><td>Ủy ban Kiểm toán Luật Thời gian</td><td>1050 năm</td><td>Chịu trách nhiệm kiểm toán sau hoạt động hồi quy thời gian, xác nhận không gây ra xáo trộn dòng thời gian không thể kiểm soát</td><td>Cơ quan kiểm toán độc lập của hoạt động thời gian, tuyến phòng thủ cuối cùng của an toàn hồi quy thời gian</td></tr><tr><td>Ủy ban Đạo đức Liên mặt phẳng</td><td>600 năm</td><td>Đặt ra và giải thích các nguyên tắc đạo đức liên mặt phẳng, phê duyệt dự án tương tác liên mặt phẳng có rủi ro cao, tiếp nhận khiếu nại vi phạm đạo đức</td><td>Cơ quan giám sát đạo đức của tương tác liên mặt phẳng, người bảo vệ chủ thể văn minh</td></tr><tr><td>Văn phòng Kiểm toán Truyền lại Kiến thức</td><td>850 năm</td><td>Chịu trách nhiệm kiểm toán hoạt động truyền lại kiến thức, đảm bảo nội dung truyền lại tuân thủ nguyên tắc &quot;chỉ truyền lại kiến thức&quot;</td><td>Cơ quan kiểm toán truyền lại kiến thức, mắt xích quan trọng trong phòng ngừa ô nhiễm liên mặt phẳng</td></tr></tbody></table><h3 id="_3-3-co-quan-nghien-cuu-va-giao-duc" tabindex="-1">3.3 Cơ quan nghiên cứu và giáo dục <a class="header-anchor" href="#_3-3-co-quan-nghien-cuu-va-giao-duc" aria-label="Permalink to &quot;3.3 Cơ quan nghiên cứu và giáo dục&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên tổ chức</th><th>Thời gian thành lập</th><th>Chức năng cốt lõi</th><th>Vai trò lịch sử</th></tr></thead><tbody><tr><td>Viện Nghiên cứu Mỏ neo</td><td>-8000 năm</td><td>Nghiên cứu cơ bản và phát triển ứng dụng cơ chế mỏ neo, xây dựng và duy trì mỏ neo nhân tạo</td><td>Cơ quan nghiên cứu cốt lõi của công nghệ mỏ neo, một trong những nguồn công nghệ của văn minh cộng sinh</td></tr><tr><td>Ủy ban Sắp xếp Hệ thống Ba trăm Bộ</td><td>-500 năm</td><td>Khai quật, sắp xếp, xác minh và tối ưu hóa liên tục hệ thống tu luyện nguồn gốc ba trăm bộ</td><td>Cơ quan sắp xếp và duy trì hệ thống ba trăm bộ, hỗ trợ kỹ thuật cho việc mở cửa tu luyện</td></tr><tr><td>Liên minh Đại học Cộng sinh</td><td>-700 năm</td><td>Tổ chức liên hợp giáo dục đại học và giáo dục tu luyện, chịu trách nhiệm đào tạo nhân tài cao cấp và nghiên cứu học thuật</td><td>Liên minh các trường đại học cao nhất của văn minh cộng sinh, cốt lõi của đào tạo nhân tài và đổi mới học thuật</td></tr><tr><td>Khoa Khảo cổ Liên mặt phẳng</td><td>550 năm</td><td>Đào tạo nhân tài chuyên ngành khảo cổ liên mặt phẳng, tiến hành nghiên cứu công nghệ khảo cổ và đổi mới phương pháp luận</td><td>Trung tâm đào tạo nhân tài và nghiên cứu phát triển công nghệ khảo cổ liên mặt phẳng</td></tr><tr><td>Viện Nghiên cứu Luật Thời gian</td><td>950 năm</td><td>Nghiên cứu lý luận cơ bản về luật thời gian và nghiên cứu phát triển công nghệ hồi quy thời gian</td><td>Cơ quan cốt lõi của nghiên cứu luật thời gian, nơi sinh ra công nghệ hồi quy thời gian</td></tr></tbody></table><h3 id="_3-4-to-chuc-quan-su-va-an-ninh" tabindex="-1">3.4 Tổ chức quân sự và an ninh <a class="header-anchor" href="#_3-4-to-chuc-quan-su-va-an-ninh" aria-label="Permalink to &quot;3.4 Tổ chức quân sự và an ninh&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên tổ chức</th><th>Thời gian thành lập</th><th>Chức năng cốt lõi</th><th>Vai trò lịch sử</th></tr></thead><tbody><tr><td>Quân đội Phòng thủ Cộng sinh</td><td>-850 năm</td><td>Lực lượng phòng thủ chính quy của văn minh cộng sinh, chịu trách nhiệm phòng thủ mặt phẳng và đối phó với các mối đe dọa bên ngoài</td><td>Lực lượng quân sự chính của văn minh cộng sinh, người bảo vệ an ninh quốc gia</td></tr><tr><td>Đội Tuần tra Mặt phẳng</td><td>520 năm</td><td>Chịu trách nhiệm tuần tra và giám sát an ninh các mặt phẳng đã khám phá, đối phó với các sự cố an ninh liên mặt phẳng</td><td>Lực lượng tuyến đầu của an ninh liên mặt phẳng, người duy trì trật tự mặt phẳng</td></tr><tr><td>Đội Cứu hộ Khẩn cấp Ô nhiễm Luật</td><td>600 năm</td><td>Chịu trách nhiệm ứng phó khẩn cấp và loại bỏ ô nhiễm trong các sự cố ô nhiễm luật và ô nhiễm năng lượng</td><td>Lực lượng ứng phó khẩn cấp của ô nhiễm luật, người bảo vệ môi trường vũ trụ</td></tr><tr><td>Nhóm Cứu hộ Khẩn cấp Nghịch lý Thời gian</td><td>1020 năm</td><td>Chịu trách nhiệm ứng phó khẩn cấp và hoạt động sửa chữa nhân quả trong các sự cố nghịch lý thời gian</td><td>Lực lượng ứng phó khẩn cấp của nghịch lý thời gian, đảm bảo cuối cùng của sự ổn định dòng thời gian</td></tr></tbody></table><h3 id="_3-5-to-chuc-dan-gian-va-xa-hoi" tabindex="-1">3.5 Tổ chức dân gian và xã hội <a class="header-anchor" href="#_3-5-to-chuc-dan-gian-va-xa-hoi" aria-label="Permalink to &quot;3.5 Tổ chức dân gian và xã hội&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên tổ chức</th><th>Thời gian thành lập</th><th>Chức năng cốt lõi</th><th>Vai trò lịch sử</th></tr></thead><tbody><tr><td>Hội nghị Cộng sinh Tất cả các Chủng tộc</td><td>-2000 năm</td><td>Cuộc họp định kỳ của đại diện tất cả các chủng tộc, thảo luận các vấn đề cộng sinh liên chủng tộc, thúc đẩy trao đổi văn hóa</td><td>Nền tảng quan trọng cho trao đổi tất cả các chủng tộc, tổ chức tiền thân của Cộng hòa Tất cả các Chủng tộc</td></tr><tr><td>Hiệp hội Người tu luyện</td><td>-600 năm</td><td>Tổ chức tự quản ngành nghề của người tu luyện, chịu trách nhiệm bảo vệ quyền lợi người tu luyện, đặt ra chuẩn mực ngành nghề</td><td>Tổ chức tự quản của người tu luyện, người thúc đẩy chuẩn hóa ngành tu luyện</td></tr><tr><td>Hiệp hội Người tiêu dùng</td><td>-650 năm</td><td>Tổ chức bảo vệ quyền lợi người tiêu dùng, chịu trách nhiệm bảo vệ quyền lợi tiêu dùng, giáo dục tiêu dùng, giám sát xã hội</td><td>Người phát ngôn quyền lợi người tiêu dùng, người giám sát xã hội trật tự thị trường</td></tr><tr><td>Liên minh Bảo vệ Môi trường</td><td>-550 năm</td><td>Tổ chức liên hợp dân gian bảo vệ môi trường, chịu trách nhiệm giám sát môi trường, giáo dục môi trường, hoạt động tình nguyện phục hồi sinh thái</td><td>Lực lượng xã hội bảo vệ môi trường, người thúc đẩy văn minh sinh thái vũ trụ</td></tr><tr><td>Hiệp hội Hữu nghị Liên mặt phẳng</td><td>580 năm</td><td>Tổ chức dân gian thúc đẩy trao đổi hữu nghị giữa các văn minh liên mặt phẳng, chịu trách nhiệm ngoại giao dân gian, trao đổi văn hóa</td><td>Lực lượng cốt lõi của ngoại giao dân gian liên mặt phẳng, cầu nối cho sự hiểu biết giữa các văn minh</td></tr></tbody></table><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Nhân vật và tổ chức quan trọng là người mang sống của lịch sử Văn minh Cộng sinh Mỏ neo. Từ những người tiên phong tư tưởng cổ xưa đến những người lãnh đạo văn minh đương đại, từ cơ quan quyền lực tối cao đến tổ chức xã hội dân gian, mỗi nhân vật và tổ chức đều đóng vai trò không thể thay thế trong câu chuyện lớn của văn minh cộng sinh. Cuộc đấu tranh và đóng góp của họ đã cùng nhau dệt nên sử thi hùng vĩ của Văn minh Cộng sinh Mỏ neo, từ không có thành có, từ nhỏ thành lớn, từ mặt phẳng riêng đến toàn bộ vũ trụ.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu Liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu Liên quan&quot;">​</a></h2><ul><li>70-Bảng Tổng quan Phân chia Kỷ nguyên</li><li>49-Khung Quản trị và Cân bằng Quyền lực</li><li>77-Thành lập Cộng hòa Tất cả các Chủng tộc</li></ul>',30)])])}const p=t(g,[["render",a]]);export{e as __pageData,p as default};
